"""Basic CSV pivot (wide) operation."""
import csv
import re
import sys

from unpivot import resolve_columns


def pivot_rows(rows, column, expression, groupby=None, column_sep="_", no_headers=False):
    if not rows:
        return []
    if no_headers:
        headers = [str(i) for i in range(max(map(len, rows)))]
        data = rows
    else:
        headers, data = rows[0], rows[1:]
    pivots = resolve_columns(column, headers)
    if not pivots:
        raise ValueError("pivot column selection is empty")
    m = re.fullmatch(r"\s*([A-Za-z_]+)\s*\((.*?)\)\s*", expression)
    if not m:
        raise ValueError("invalid aggregation expression")
    op, arg = m.group(1).lower(), m.group(2).strip()
    if op not in ("first", "last", "sum", "count", "min", "max", "mean"):
        raise ValueError("unsupported aggregation: " + op)
    vals = [] if arg == "*" else resolve_columns(arg, headers)
    if not vals and arg != "*":
        raise ValueError("aggregation column not found: " + arg)
    value_idx = vals[0] if vals else None
    if groupby is None:
        groups = [i for i in range(len(headers)) if i not in pivots and i != value_idx]
    else:
        groups = resolve_columns(groupby, headers)
    pivot_values = []
    buckets = {}
    group_values = {}
    for row in data:
        row = list(row) + [""] * max(0, len(headers) - len(row))
        pv = column_sep.join(row[i] for i in pivots)
        if pv not in buckets:
            pivot_values.append(pv)
            buckets[pv] = {}
        key = tuple(row[i] for i in groups)
        if key not in group_values:
            group_values[key] = [row[i] for i in groups]
        slot = buckets[pv]
        if key not in slot:
            slot[key] = []
        slot[key].append("1" if value_idx is None else row[value_idx])
    out = [[headers[i] for i in groups] + pivot_values]
    for key, gv in group_values.items():
        result = gv[:]
        for pv in pivot_values:
            items = buckets[pv].get(key, [])
            value = ""
            if items:
                if op == "first": value = items[0]
                elif op == "last": value = items[-1]
                elif op == "count": value = str(len(items))
                elif op in ("sum", "mean"):
                    nums = [float(x) for x in items if x != ""]
                    if nums:
                        total = sum(nums) / len(nums) if op == "mean" else sum(nums)
                        value = str(int(total)) if total.is_integer() else str(total)
                elif op == "min": value = min(items)
                elif op == "max": value = max(items)
            result.append(value)
        out.append(result)
    return out


def run(command, argv):
    if command not in ("pivot", "pivot-wider"):
        return False
    delim, output, groupby, sep = ",", None, None, "_"
    no_headers = False
    pos = []
    i = 0
    try:
        while i < len(argv):
            a = argv[i]
            if a in ("-h", "--help"):
                print("Pivot distinct values from a column into separate columns.\n\nUsage: xan pivot [options] <column> <expr> [<input>]\n\nOptions: -g, --groupby <columns>  --column-sep <sep>\nCommon: -n, --no-headers  -d, --delimiter <char>  -o, --output <file>")
                return True
            if a in ("-n", "--no-headers"): no_headers = True
            elif a in ("-d", "--delimiter", "-o", "--output", "-g", "--groupby", "--column-sep"):
                i += 1
                if i >= len(argv): raise ValueError("missing value for " + a)
                v = argv[i]
                if a in ("-d", "--delimiter"): delim = v
                elif a in ("-o", "--output"): output = v
                elif a in ("-g", "--groupby"): groupby = v
                else: sep = v
            elif a.startswith("-") and a != "-": raise ValueError("unexpected option: " + a)
            else: pos.append(a)
            i += 1
        if len(delim) != 1: raise ValueError("delimiter must be a single character")
        if not pos:
            col, expr, path = "name", "first(value)", "-"
        elif len(pos) == 1:
            col, expr, path = "name", "first(value)", pos[0]
        elif len(pos) in (2, 3):
            col, expr = pos[:2]
            path = pos[2] if len(pos) == 3 else "-"
        else: raise ValueError("expected column, expression and optional input")
        src = open(path, newline="", encoding="utf-8-sig") if path != "-" else sys.stdin
        try: rows = list(csv.reader(src, delimiter=delim))
        finally:
            if src is not sys.stdin: src.close()
        result = pivot_rows(rows, col, expr, groupby, sep, no_headers)
        dst = open(output, "w", newline="", encoding="utf-8") if output else sys.stdout
        try: csv.writer(dst, delimiter=delim, lineterminator="\n").writerows(result)
        finally:
            if dst is not sys.stdout: dst.close()
    except (OSError, csv.Error, ValueError, IndexError) as e:
        print("error: " + str(e), file=sys.stderr)
    return True
