                if a in ('-s','--start'):start=int(v)
                elif a=='--step':step=int(v)
                elif a in ('-c','--column-name'):name=v
                else:out=v
            elif a in ('-i','--inclusive'):inclusive=True
            elif a.startswith('-') and a!='-':raise ValueError('unexpected option: '+a)
            elif end is None:end=int(a)
