            i+=1
        if end is None:raise ValueError('missing range end')
        if step==0:raise ValueError('step cannot be zero')
        stop=end+(1 if step>0 else -1) if inclusive else end
        write([[name]]+[[str(x)] for x in range(start,stop,step)],',',out);return
    if cmd=='sort':
        sel=None; numeric=False; reverse=False; uniq=False; out=None; delim=','; nohead=False; check=False
        pos=[];i=0
        while i<len(args):
            a=args[i]
            if a in ('-s','--select','-o','--output','-d','--delimiter'):
