"""Small standalone commands for the xan-compatible CLI."""
import csv
import sys
from csvutil import nonblank_rows


def _args(argv):
    opts = {"no_headers": False, "delimiter": ",", "output": None}
    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-n", "--no-headers"):
            opts["no_headers"] = True
        elif a in ("-d", "--delimiter", "-o", "--output"):
            i += 1
            if i >= len(argv): raise ValueError("missing value for " + a)
            opts["delimiter" if a in ("-d", "--delimiter") else "output"] = argv[i]
        elif a.startswith("--delimiter="):
            opts["delimiter"] = a.split("=", 1)[1]
        elif a.startswith("--output="):
            opts["output"] = a.split("=", 1)[1]
        elif a in ("--tabs", "--crlf", "--ascii", "--quote-always", "--quote-never"):
            pass
        elif a in ("-t", "--out-delimiter", "--quote", "--escape"):
            i += 1
            if i >= len(argv): raise ValueError("missing value for " + a)
        elif a == "--":
            positional.extend(argv[i + 1:]); break
        elif a.startswith("-") and a != "-":
            raise ValueError("unexpected option: " + a)
        else:
            positional.append(a)
        i += 1
    if len(opts["delimiter"]) != 1: raise ValueError("delimiter must be a single character")
    return opts, positional


def _read(path, delim):
    src = open(path, "r", newline="", encoding="utf-8-sig") if path and path != "-" else sys.stdin
    try: return nonblank_rows(csv.reader(src, delimiter=delim))
    finally:
        if src is not sys.stdin: src.close()


def _write(rows, path, delim, **kwargs):
    dest = open(path, "w", newline="", encoding="utf-8") if path else sys.stdout
    try:
        w = csv.writer(dest, delimiter=delim, lineterminator=kwargs.get("lineterminator", "\n"),
                       quotechar=kwargs.get("quotechar", '"'), quoting=kwargs.get("quoting", csv.QUOTE_MINIMAL),
                       escapechar=kwargs.get("escapechar"))
        w.writerows(rows)
    finally:
        if dest is not sys.stdout: dest.close()


def run(command, argv):
    if command not in ("reverse", "fmt"):
        return False
    try:
        opts, pos = _args(argv)
        if len(pos) > 1: raise ValueError("expected at most one input file")
        path = pos[0] if pos else None
        rows = _read(path, opts["delimiter"])
        if command == "reverse":
            if opts["no_headers"]: rows.reverse()
            elif rows: rows = rows[:1] + rows[:0:-1]
            _write(rows, opts["output"], opts["delimiter"])
            return True
        outdelim, term, quote, quoting, escape = ",", "\n", '"', csv.QUOTE_MINIMAL, None
        i = 0
        while i < len(argv):
            a = argv[i]
            if a in ("-t", "--out-delimiter", "--quote", "--escape"):
                i += 1
                if i >= len(argv): raise ValueError("missing value for " + a)
                if a in ("-t", "--out-delimiter"): outdelim = argv[i]
                elif a == "--quote": quote = argv[i]
                else: escape = argv[i]
            elif a == "--tabs": outdelim = "\t"
            elif a == "--crlf": term = "\r\n"
            elif a == "--quote-always": quoting = csv.QUOTE_ALL
            elif a == "--quote-never": quoting = csv.QUOTE_NONE
            elif a == "--ascii": outdelim = "\x1f"; term = "\x1e"
            i += 1
        if len(outdelim) != 1 or len(quote) != 1 or (escape is not None and len(escape) != 1):
            raise ValueError("delimiter, quote and escape must be single characters")
        _write(rows, opts["output"], outdelim, lineterminator=term, quotechar=quote, quoting=quoting, escapechar=escape)
        return True
    except (OSError, csv.Error, ValueError) as e:
        print("error: " + str(e), file=sys.stderr)
        return True

